<?php if(can_write()): ?><section class="panel mb-4"><h2>Registrar incidencia</h2><form method="post" action="<?= e(url('incident-save')) ?>"><?= csrf_field() ?><div class="row g-3 mt-1"><div class="col-md-8"><label class="form-label" for="title">Título</label><input id="title" name="title" class="form-control" required maxlength="150"></div><div class="col-md-4"><label class="form-label" for="severity">Severidad</label><select id="severity" name="severity" class="form-select"><?php foreach(['BAJA','MEDIA','ALTA','CRITICA'] as $v): ?><option><?= $v ?></option><?php endforeach ?></select></div><div class="col-12"><label class="form-label" for="description">Descripción, pasos y resultado esperado</label><textarea id="description" name="description" class="form-control" rows="3" maxlength="5000" required></textarea></div></div><button class="btn btn-primary mt-3">Registrar incidencia</button></form></section><?php endif ?><section class="panel"><h2>Seguimiento · últimas 100 incidencias</h2><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Incidencia</th><th>Severidad</th><th>Responsable</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['id']) ?></td><td><strong><?= e($r['title']) ?></strong><p class="small text-secondary mb-1 preserve-lines"><?= e($r['description']) ?></p><small><?= e($r['created_at']) ?></small></td><td><?= e($r['severity']) ?></td><td><?= e($r['name']) ?></td><td><?php if(is_admin()): ?><form class="d-flex gap-1" method="post" action="<?= e(url('incident-save')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($r['id']) ?>"><select class="form-select form-select-sm" name="status" aria-label="Estado de incidencia"><?php foreach(['ABIERTA','EN_PROCESO','RESUELTA'] as $v): ?><option <?= $v===$r['status']?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select><button class="btn btn-sm btn-light">Guardar</button></form><?php else: ?><?= e($r['status']) ?><?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="5" class="empty-state">No hay incidencias registradas.</td></tr><?php endif ?></tbody></table></div></section>
